<script setup lang="ts">type LinkRow={id:string;name:string;url:string;logo:string|null;description:string|null;group:string|null;position:number;visible:boolean};definePageMeta({layout:'admin',middleware:'admin'});const {data,refresh}=await useFetch<LinkRow[]>('/api/admin/links');const csrf=useCsrf();const open=ref(false);const edit=ref<LinkRow|null>(null);const m=reactive({name:'',url:'',logo:'',description:'',group:'',position:0,visible:true});function start(row?:LinkRow){edit.value=row||null;Object.assign(m,{name:row?.name||'',url:row?.url||'',logo:row?.logo||'',description:row?.description||'',group:row?.group||'',position:row?.position||0,visible:row?.visible??true});open.value=true}async function save(){await $fetch(edit.value?`/api/admin/links/${edit.value.id}`:'/api/admin/links',{method:edit.value?'PUT':'POST',headers:csrf.value,body:{...m,logo:m.logo||null,description:m.description||null,group:m.group||null}});open.value=false;await refresh()}async function remove(l:LinkRow){await $fetch(`/api/admin/links/${l.id}`,{method:'DELETE',headers:csrf.value});await refresh()}</script><template><div><div class="flex justify-between"><h1 class="text-3xl font-semibold">友链</h1><button class="rounded-full px-5 py-2 text-white" style="background:var(--accent)" @click="start()">添加友链</button></div><div v-for="l in data||[]" :key="l.id" class="mt-4 flex justify-between rounded-xl border p-4" style="border-color:var(--border)"><div class="flex gap-3"><img v-if="l.logo" :src="l.logo" :alt="l.name" class="h-10 w-10 rounded object-cover"><div><strong>{{l.name}}</strong> <small>{{l.group}}</small><p>{{l.url}} · {{l.visible?'显示':'隐藏'}}</p></div></div><span><button @click="start(l)">编辑</button> <button @click="remove(l)">删除</button></span></div><div v-if="open" class="fixed inset-0 z-50 grid place-items-center bg-black/50 p-4" @click.self="open=false"><form class="w-full max-w-lg rounded-2xl p-6" style="background:var(--surface)" @submit.prevent="save"><h2 class="text-xl font-semibold">编辑友链</h2><div class="mt-4 grid gap-3"><input v-model="m.name" required placeholder="名称" class="rounded border bg-transparent p-2"><input v-model="m.url" required type="url" placeholder="网站 URL" class="rounded border bg-transparent p-2"><input v-model="m.logo" type="url" placeholder="Logo URL" class="rounded border bg-transparent p-2"><textarea v-model="m.description" placeholder="描述" class="rounded border bg-transparent p-2"/><input v-model="m.group" placeholder="分组" class="rounded border bg-transparent p-2"><input v-model.number="m.position" type="number" placeholder="顺序" class="rounded border bg-transparent p-2"><label><input v-model="m.visible" type="checkbox"> 显示</label></div><div class="mt-5 flex justify-end gap-3"><button type="button" @click="open=false">取消</button><button class="rounded-lg px-4 py-2 text-white" style="background:var(--accent)">保存</button></div></form></div></div></template>
